CREATE TABLE IF NOT EXISTS tesoreria.dues_cash_shifts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), desk_id text NOT NULL, assigned_operator_id uuid NOT NULL REFERENCES public.operators(id) ON DELETE RESTRICT, status text NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN','CLOSED')), opening_tenders jsonb NOT NULL DEFAULT '{}', operator_id uuid NOT NULL REFERENCES public.operators(id) ON DELETE RESTRICT, authorization_evidence jsonb NOT NULL DEFAULT '{}', caller_key text NOT NULL, request_fingerprint char(64) NOT NULL, opened_at timestamptz NOT NULL DEFAULT now(), closed_at timestamptz, CONSTRAINT dues_cash_shift_fingerprint_check CHECK (length(btrim(request_fingerprint)) = 64));
CREATE UNIQUE INDEX IF NOT EXISTS dues_cash_shift_open_desk_unique ON tesoreria.dues_cash_shifts (desk_id) WHERE status = 'OPEN';
CREATE UNIQUE INDEX IF NOT EXISTS dues_cash_shift_operator_key_unique ON tesoreria.dues_cash_shifts (operator_id, caller_key);
CREATE TABLE IF NOT EXISTS tesoreria.dues_cash_tenders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), shift_id uuid NOT NULL REFERENCES tesoreria.dues_cash_shifts(id) ON DELETE RESTRICT, direction text NOT NULL CHECK (direction IN ('INCOME','EXPENSE')), tender text NOT NULL, amount numeric(14,2) NOT NULL CHECK (amount > 0), source_type text NOT NULL CHECK (source_type IN ('SETTLEMENT','GASTO','MANUAL')), source_id uuid, reason text, operator_id uuid NOT NULL REFERENCES public.operators(id) ON DELETE RESTRICT, caller_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS dues_cash_tender_source_unique ON tesoreria.dues_cash_tenders (shift_id, source_type, source_id) WHERE source_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS tesoreria.dues_cash_shift_expenses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), shift_id uuid NOT NULL REFERENCES tesoreria.dues_cash_shifts(id) ON DELETE RESTRICT, gasto_id uuid NOT NULL UNIQUE REFERENCES tesoreria.gastos(id) ON DELETE RESTRICT, operator_id uuid NOT NULL REFERENCES public.operators(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tesoreria.dues_cash_closes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), shift_id uuid NOT NULL UNIQUE REFERENCES tesoreria.dues_cash_shifts(id) ON DELETE RESTRICT, expected_tenders jsonb NOT NULL, counted_tenders jsonb NOT NULL, discrepancy jsonb NOT NULL, reason text, operator_id uuid NOT NULL REFERENCES public.operators(id) ON DELETE RESTRICT, authorization_evidence jsonb NOT NULL DEFAULT '{}', caller_key text NOT NULL, request_fingerprint char(64) NOT NULL, closed_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT dues_cash_close_reason_check CHECK (discrepancy = '{}'::jsonb OR (reason IS NOT NULL AND btrim(reason) <> '')));
CREATE UNIQUE INDEX IF NOT EXISTS dues_cash_close_operator_key_unique ON tesoreria.dues_cash_closes (operator_id, caller_key);
CREATE TABLE IF NOT EXISTS tesoreria.gasto_compensations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), original_gasto_id uuid NOT NULL REFERENCES tesoreria.gastos(id) ON DELETE RESTRICT, compensating_gasto_id uuid NOT NULL REFERENCES tesoreria.gastos(id) ON DELETE RESTRICT, reason text NOT NULL CHECK (btrim(reason) <> ''), operator_id uuid NOT NULL REFERENCES public.operators(id) ON DELETE RESTRICT, caller_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (original_gasto_id, caller_key));
CREATE OR REPLACE FUNCTION tesoreria.reject_dues_cash_close_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'cash closes are immutable' USING ERRCODE = '55000'; END $$;
DROP TRIGGER IF EXISTS dues_cash_close_immutable ON tesoreria.dues_cash_closes;
CREATE TRIGGER dues_cash_close_immutable BEFORE UPDATE OR DELETE ON tesoreria.dues_cash_closes FOR EACH ROW EXECUTE FUNCTION tesoreria.reject_dues_cash_close_mutation();
CREATE OR REPLACE FUNCTION tesoreria.reject_closed_cash_tender() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP <> 'INSERT' OR EXISTS (SELECT 1 FROM tesoreria.dues_cash_shifts WHERE id = COALESCE(NEW.shift_id, OLD.shift_id) AND status = 'CLOSED') THEN RAISE EXCEPTION 'closed cash shifts are immutable' USING ERRCODE = '55000'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS dues_cash_tender_immutable ON tesoreria.dues_cash_tenders;
CREATE TRIGGER dues_cash_tender_immutable BEFORE INSERT OR UPDATE OR DELETE ON tesoreria.dues_cash_tenders FOR EACH ROW EXECUTE FUNCTION tesoreria.reject_closed_cash_tender();
DROP TRIGGER IF EXISTS dues_cash_expense_immutable ON tesoreria.dues_cash_shift_expenses;
CREATE TRIGGER dues_cash_expense_immutable BEFORE INSERT OR UPDATE OR DELETE ON tesoreria.dues_cash_shift_expenses FOR EACH ROW EXECUTE FUNCTION tesoreria.reject_closed_cash_tender();
